// BatchingDemo.jsx
import { useState } from 'react';

let renders = 0;

export function BatchingDemo() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  renders += 1; // tylko do obserwacji

  async function load() {
    setLoading(true);
    setError(null);
    await new Promise((r) => setTimeout(r, 300));
    // trzy aktualizacje po await — jeden render (React 18+)
    setItems(['A', 'B', 'C']);
    setLoading(false);
    setError(null);
  }

  return (
    <div>
      <button type="button" onClick={load}>Wczytaj</button>
      <p>{loading ? 'Ładowanie…' : items.join(', ')} {error}</p>
      <small>Renderów: {renders}</small>
    </div>
  );
}

